from pathlib import Path

css = Path('app/site.css')
s = css.read_text()
marker = '/* Audio Player final verified feature-layer styling */'
if marker not in s:
    s += '''\n\n@layer site-features {\n  /* Audio Player final verified feature-layer styling */\n  .audio-player-dock {\n    background: var(--site-paper);\n    background-image: none;\n    backdrop-filter: none;\n    border: 1px solid var(--site-line);\n    border-radius: 12px;\n    box-shadow: 0 10px 28px color-mix(in srgb, var(--site-ink) 10%, transparent);\n    opacity: 1;\n    overflow: visible;\n  }\n\n  .audio-player-dock.is-expanded {\n    max-width: calc(100vw - 28px);\n    width: min(640px, calc(100vw - 28px));\n  }\n\n  .audio-player-dock.is-collapsed {\n    max-width: calc(100vw - 24px);\n    width: min(330px, calc(100vw - 24px));\n  }\n\n  .audio-player-dock.is-expanded .audio-player-mini {\n    align-items: center;\n    background: var(--site-paper);\n    border: 0;\n    display: grid;\n    gap: 8px;\n    grid-template-columns: minmax(0, 1fr) 30px;\n    min-height: 48px;\n    padding: 13px 16px 2px;\n  }\n\n  .audio-player-dock.is-expanded .audio-player-title {\n    grid-column: 1;\n    justify-self: stretch;\n    max-width: none;\n    min-width: 0;\n    padding: 0;\n    text-align: left;\n    width: 100%;\n  }\n\n  .audio-player-dock.is-expanded .audio-player-title strong {\n    display: block;\n    font-size: 14px;\n    font-weight: 720;\n    line-height: 1.35;\n    max-width: none;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    width: 100%;\n  }\n\n  .audio-player-dock.is-expanded .audio-player-title span,\n  .audio-player-dock.is-expanded .audio-player-mini-time,\n  .audio-player-dock.is-expanded .audio-player-mini-toggle,\n  .audio-player-dock.is-expanded .audio-player-mini-close {\n    display: none;\n  }\n\n  .audio-player-dock.is-expanded .audio-player-expand {\n    background: transparent;\n    border: 0;\n    color: var(--site-muted);\n    grid-column: 2;\n    height: 30px;\n    min-height: 30px;\n    min-width: 30px;\n    padding: 0;\n    width: 30px;\n  }\n\n  .audio-player-details {\n    background: var(--site-paper);\n    display: flex;\n    flex-direction: column;\n    gap: 7px;\n    padding: 0 16px 14px;\n  }\n\n  .audio-section-companion {\n    border: 0;\n    margin: 0;\n    order: -1;\n    padding: 0;\n    position: relative;\n  }\n\n  .audio-section-summary {\n    align-items: center;\n    display: grid;\n    gap: 8px;\n    grid-template-columns: minmax(0, 1fr) auto;\n    min-height: 31px;\n  }\n\n  .audio-section-current small {\n    color: var(--site-muted);\n    display: block;\n    font-size: 10px;\n    line-height: 1.3;\n    margin: 0;\n  }\n\n  .audio-section-current strong {\n    color: var(--site-primary);\n    display: block;\n    font-size: 11px;\n    line-height: 1.3;\n    margin-top: 2px;\n  }\n\n  .audio-section-toggle {\n    align-items: center;\n    background: transparent;\n    border: 1px solid var(--site-line);\n    border-radius: 7px;\n    color: var(--site-ink-soft);\n    display: inline-flex;\n    gap: 4px;\n    min-height: 29px;\n    padding: 0 8px;\n  }\n\n  .audio-section-toggle:hover {\n    background: color-mix(in srgb, var(--site-primary) 5%, var(--site-paper));\n    border-color: color-mix(in srgb, var(--site-primary) 34%, var(--site-line));\n  }\n\n  .audio-section-panel {\n    background: var(--site-paper);\n    border: 1px solid var(--site-line);\n    border-radius: 10px;\n    box-shadow: 0 12px 28px color-mix(in srgb, var(--site-ink) 13%, transparent);\n    overflow: auto;\n    padding: 5px;\n  }\n\n  .audio-section-list { gap: 1px; }\n  .audio-section-list button {\n    border-radius: 7px;\n    gap: 8px;\n    grid-template-columns: 9px minmax(0, 1fr) auto;\n    min-height: 30px;\n    padding: 4px 7px;\n  }\n  .audio-section-list strong { font-size: 11px; line-height: 1.25; }\n  .audio-section-list time { font-size: 9px; }\n\n  .audio-player-timeline {\n    height: 42px;\n    overflow: visible;\n    padding: 0;\n    position: relative;\n  }\n\n  .audio-player-dock.has-audio-sections .audio-player-timeline > input[type="range"] {\n    appearance: none;\n    background: transparent;\n    border: 0;\n    box-shadow: none;\n    cursor: pointer;\n    height: 24px;\n    margin: 0;\n    outline: 0;\n    padding: 0;\n    position: relative;\n    width: 100%;\n    z-index: 5;\n  }\n  .audio-player-dock.has-audio-sections .audio-player-timeline > input[type="range"]::-webkit-slider-runnable-track { background: transparent; border: 0; height: 2px; }\n  .audio-player-dock.has-audio-sections .audio-player-timeline > input[type="range"]::-moz-range-track { background: transparent; border: 0; height: 2px; }\n  .audio-player-dock.has-audio-sections .audio-player-timeline > input[type="range"]::-webkit-slider-thumb {\n    -webkit-appearance: none;\n    background: var(--site-paper);\n    border: 1.5px solid var(--site-primary);\n    border-radius: 50%;\n    box-shadow: 0 0 0 4px color-mix(in srgb, var(--site-primary) 7%, transparent);\n    height: 11px;\n    margin-top: -4.5px;\n    width: 11px;\n  }\n  .audio-player-dock.has-audio-sections .audio-player-timeline > input[type="range"]::-moz-range-thumb {\n    background: var(--site-paper);\n    border: 1.5px solid var(--site-primary);\n    border-radius: 50%;\n    box-shadow: 0 0 0 4px color-mix(in srgb, var(--site-primary) 7%, transparent);\n    height: 11px;\n    width: 11px;\n  }\n\n  .audio-section-node-layer { height: 24px; top: 0; z-index: 6; }\n  .audio-section-track-base, .audio-section-track-progress { border-radius: 1px; height: 2px; top: 11px; }\n  .audio-section-track-base { background: color-mix(in srgb, var(--site-line-strong) 54%, var(--site-paper)); }\n  .audio-section-track-progress { background: var(--site-primary); }\n  .audio-section-node { height: 7px; top: 7.5px; width: 7px; }\n  .audio-section-node::before { content: ""; inset: -8px; position: absolute; }\n  .audio-section-node:hover, .audio-section-node:focus-visible {\n    background: var(--site-primary);\n    border-color: var(--site-primary);\n    box-shadow: 0 0 0 5px color-mix(in srgb, var(--site-primary) 12%, transparent), 0 0 18px color-mix(in srgb, var(--site-primary) 28%, transparent);\n    transform: translateX(-50%) scale(1.35);\n  }\n  .audio-section-node-tooltip { max-width: 190px; min-width: 118px; padding: 6px 8px; }\n  .audio-section-node.is-edge-start .audio-section-node-tooltip { left: -8px; transform: translate(0, 5px); }\n  .audio-section-node.is-edge-start:hover .audio-section-node-tooltip, .audio-section-node.is-edge-start:focus-visible .audio-section-node-tooltip { transform: translate(0, 0); }\n  .audio-section-node.is-edge-end .audio-section-node-tooltip { left: auto; right: -8px; transform: translate(0, 5px); }\n  .audio-section-node.is-edge-end:hover .audio-section-node-tooltip, .audio-section-node.is-edge-end:focus-visible .audio-section-node-tooltip { transform: translate(0, 0); }\n  .audio-player-timeline > div:last-child { font-size: 10px; margin-top: -2px; }\n\n  .audio-player-controls {\n    align-items: center;\n    border-top: 0;\n    display: flex;\n    gap: 7px;\n    padding: 2px 0 0;\n  }\n  .audio-player-transport { display: flex; flex: 0 0 auto; gap: 2px; order: 1; }\n  .audio-player-rate { flex: 0 0 auto; min-width: 62px; order: 2; }\n  .audio-player-rate > span { display: none; }\n  .audio-player-rate select { min-height: 30px; padding: 0 24px 0 8px; }\n  .audio-player-transport :is(.audio-player-skip, .audio-player-chapter-control) {\n    background: transparent; border: 0; border-radius: 50%; height: 31px; min-height: 31px; min-width: 31px; padding: 0; width: 31px;\n  }\n  .audio-player-main-toggle { border-radius: 50%; height: 42px; margin-inline: 2px; width: 42px; }\n\n  .audio-player-utilities {\n    align-items: center;\n    display: flex;\n    flex: 1 1 auto;\n    gap: 4px;\n    justify-content: flex-end;\n    margin-left: auto;\n    min-width: 0;\n    order: 3;\n    position: relative;\n  }\n  .audio-player-volume { align-items: center; color: var(--site-muted); display: flex; flex: 1 1 90px; gap: 5px; max-width: 118px; min-width: 74px; }\n  .audio-player-volume svg { flex: 0 0 auto; height: 14px; width: 14px; }\n  .audio-player-volume input[type="range"] { appearance: none; background: transparent; height: 18px; margin: 0; min-width: 0; padding: 0; width: 100%; }\n  .audio-player-volume input[type="range"]::-webkit-slider-runnable-track { background: color-mix(in srgb, var(--site-primary) 72%, var(--site-line)); border-radius: 1px; height: 2px; }\n  .audio-player-volume input[type="range"]::-moz-range-track { background: color-mix(in srgb, var(--site-primary) 72%, var(--site-line)); border-radius: 1px; height: 2px; }\n  .audio-player-volume input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; background: var(--site-paper); border: 1.5px solid var(--site-primary); border-radius: 50%; height: 9px; margin-top: -3.5px; width: 9px; }\n  .audio-player-volume input[type="range"]::-moz-range-thumb { background: var(--site-paper); border: 1.5px solid var(--site-primary); border-radius: 50%; height: 9px; width: 9px; }\n\n  .audio-player-utility, .audio-player-settings > summary {\n    align-items: center; background: transparent; border: 0; border-radius: 50%; color: var(--site-ink-soft); cursor: pointer; display: inline-flex; height: 30px; justify-content: center; list-style: none; min-height: 30px; min-width: 30px; padding: 0; width: 30px;\n  }\n  .audio-player-settings > summary::-webkit-details-marker { display: none; }\n  .audio-player-settings { position: relative; }\n  .audio-player-settings-panel {\n    background: var(--site-paper);\n    border: 1px solid var(--site-line);\n    border-radius: 10px;\n    bottom: calc(100% + 9px);\n    box-shadow: 0 14px 34px color-mix(in srgb, var(--site-ink) 16%, transparent);\n    padding: 8px;\n    position: absolute;\n    right: 0;\n    width: 244px;\n    z-index: 30;\n  }\n  .audio-player-settings-panel .audio-player-options { border: 0; display: grid; gap: 3px; overflow: visible; padding: 0; }\n  .audio-player-settings-panel .audio-player-option { align-items: center; background: transparent; border: 0; border-radius: 7px; display: grid; gap: 7px; grid-template-columns: 22px minmax(0, 1fr); justify-content: start; min-height: 34px; padding: 5px 7px; text-align: left; width: 100%; }\n  .audio-player-settings-panel .audio-player-option:hover { background: color-mix(in srgb, var(--site-primary) 6%, var(--site-paper)); }\n  .audio-player-settings-panel .audio-player-option span small { display: inline; margin-left: 5px; }\n  .audio-player-settings-panel .audio-player-option-select select { min-height: 28px; width: 100%; }\n  .audio-player-settings-actions { border-top: 1px solid var(--site-line); display: grid; gap: 5px; grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 7px; padding-top: 7px; }\n  .audio-player-settings-actions button { background: transparent; border: 1px solid var(--site-line); border-radius: 7px; color: var(--site-ink-soft); min-height: 30px; }\n  .audio-player-settings-panel .audio-player-queue-panel { background: var(--site-surface-muted); border: 0; border-radius: 7px; box-shadow: none; margin-top: 6px; max-height: 165px; overflow: auto; padding: 7px; position: static; }\n\n  .audio-question-choice { max-width: 330px; padding: 14px; }\n  .audio-question-choice-options { gap: 7px; }\n  .audio-question-choice-option { border-radius: 7px; min-height: 34px; padding: 0 10px; }\n\n  @media (min-width: 701px) {\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) { min-height: 304px; width: min(930px, calc(100vw - 28px)); }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-player-details { min-height: 246px; padding-right: 324px; position: relative; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-player-controls { margin-top: auto; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-section-panel { max-height: 244px; position: absolute; right: -308px; top: 0; width: 292px; }\n  }\n\n  @media (max-width: 700px) {\n    .audio-player-dock.is-expanded { max-width: calc(100vw - 24px); width: calc(100vw - 24px); }\n    .audio-player-dock.is-expanded .audio-player-mini { grid-template-columns: minmax(0, 1fr) 30px; min-height: 44px; padding: 11px 12px 1px; }\n    .audio-player-dock.is-expanded .audio-player-title { grid-column: 1; max-width: none; min-width: 0; width: 100%; }\n    .audio-player-dock.is-expanded .audio-player-title strong { display: block; font-size: 11px; line-height: 1.35; max-width: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; width: 100%; }\n    .audio-player-dock.is-expanded .audio-player-expand { grid-column: 2; }\n    .audio-player-details { gap: 6px; padding: 0 12px 12px; }\n    .audio-section-summary { min-height: 30px; }\n    .audio-player-controls { display: grid; gap: 7px 8px; grid-template-columns: auto minmax(0, 1fr); }\n    .audio-player-transport { grid-column: 1 / -1; justify-content: space-around; order: 1; width: 100%; }\n    .audio-player-rate { grid-column: 1; order: 2; }\n    .audio-player-utilities { display: grid; gap: 4px; grid-column: 2; grid-template-columns: minmax(0, 1fr) 30px; margin-left: 0; order: 3; width: 100%; }\n    .audio-player-volume { max-width: none; width: 100%; }\n    .audio-player-fullscreen { display: none; }\n    .audio-player-settings-panel { right: 0; width: min(260px, calc(100vw - 48px)); }\n    .audio-section-panel { margin-top: 4px; max-height: min(48vh, 320px); position: static; width: 100%; }\n    .audio-section-list button { min-height: 34px; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-player-timeline,\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-player-controls { display: none; }\n  }\n}\n'''
